  // TODO: return flattened object
}

solution:
const flatObj = obj => {
  const res = {};
  const flatten = (o, prefix='') => {
    for (const [k,v] of Object.entries(o)) {
      if (typeof v === 'object' && v !== null && !Array.isArray(v)) flatten(v, prefix+k+'.');
      else res[prefix+k] = v;
    }
  };
  flatten(obj);
  return res;
};

