  // TODO: return longest increasing subsequence
}

solution:
const incSubseq = arr => {
  const dp = arr.map(()=>[]);
  dp[0] = [arr[0]];
  for (let i=1;i<arr.length;i++) {
    for (let j=0;j<i;j++) {
      if (arr[j]<arr[i] && dp[j].length>=dp[i].length) dp[i]=[...dp[j]];
    }
    dp[i].push(arr[i]);
  }
  return dp.sort((a,b)=>b.length-a.length)[0];
};

