const longestSeq = (arr) => {
  // TODO: return length of longest consecutive sequence
}

solution:
const longestSeq = arr => {
  const set = new Set(arr);
  let max = 0;
  for (const n of set) {
    if (!set.has(n-1)) {
      let len=1;
      while(set.has(n+len)) len++;
      max=Math.max(max,len);
    }
  }
  return max;
};
